import React from "react";
import { observable, action, computed, toJS, makeObservable } from 'mobx';
import { JSONSchemaCustom } from "@/components/schema";
import { Pattern } from "@/types/pattern";
import ajax, { uploadOSSFile } from "@/utils/ajax";
import plugin from "@/store/plugin";
import { Message } from "@arco-design/web-react";
import { CustomPageStore, moduleStore } from "react-converter-code";
import dir from "@/store/dir";
import { PluginCodeInfo } from "@/types/plugin";


class Store {

    @observable visible = false;
    @action setVisible = (bool) => {
        this.visible = bool;
    }

    downItem: any = {};
    @observable downloadVisible = false;
    @action setDownloadVisible = (bool) => {
        this.downloadVisible = bool;
    }

    @observable publishVersions = [];
    @action setPublishVersions = (list) => {
        this.publishVersions = list;
    }

    @observable selected = "";
    @action setSelected = (uid: string) => {
        this.selected = uid;
    }

    @computed get versions(){
        return toJS(this.publishVersions).map((o) => ({
            value: o.versionNumber,
            label: o.versionNumber
        }))
    }

    initValues = {};

    schema: JSONSchemaCustom = {
        type: "object",
        properties: {
            versionNumber: {
                "title": "应用版本号",
                description: "应用版本格式要符合 xx.xx.xx",
                formItemProps: {
                    rules: [
                        { required: true },
                        { match: new RegExp(Pattern.version), message: "请检查版本号格式是否正确" },
                        { 
                            validator: (value, callback) => {
                                const versions = this.list.map((item) => item.versionNumber);
                                if(versions.length){
                                    if(versions.includes(value)){
                                        return callback("当前版本号已经存在")
                                    }
                                    if(value < versions[0]) return callback(`当前版本号需要大于${versions[0]}`);
                                }
                            },
                        }
                    ]
                }
            },
            description: {
                title: "版本描述",
                format: "text"
            }
        },
        required: ['versionNumber']
    }

    constructor(){
        makeObservable(this);
        this.init();
    }

    @observable list = [];
    @action setList = (data) => {
        this.list = data;
    }


    init = () => {
        // 获取最新的50个版本
        ajax.post('/apijson/get', {
            "PluginVersion[]": {
                "count": 50,
                "PluginVersion": {
                    pluginId: plugin.info.id,
                    "@order": "versionNumber-"
                }
            }
        }).then((res) => {
            this.setList(res.PluginVersion)
            this.getPublishVersion();
        })
    }


    // 获取线上可用版本
    getPublishVersion = () => {
        ajax.post('/apijson/get', {
            "PluginVersion[]": {
                "count": 0,
                "PluginVersion": {
                    pluginId: plugin.info.id,
                    "isReleased": 1,
                    "@column": "id,versionNumber",
                    "@order": "versionNumber-"
                }
            }
        }).then((res) => {
            this.setPublishVersions(res.PluginVersion);
        })
    }



    incrementVersion = () => {
        if(!this.list[0]) return "1.0.0";
        const { versionNumber: version } = this.list[0]
        // 将版本号拆分成主版本号、次版本号和修订版本号
        var parts = version.split('.');
        var major = parseInt(parts[0], 10);
        var minor = parseInt(parts[1], 10);
        var patch = parseInt(parts[2], 10);
    
        // 将修订版本号加一
        patch++;
    
        // 如果修订版本号达到10，增加次版本号，修订版本号重置为0
        if (patch === 10) {
            minor++;
            patch = 0;
        }
    
        // 如果次版本号达到10，增加主版本号，次版本号和修订版本号都重置为0
        if (minor === 10) {
            major++;
            minor = 0;
            patch = 0;
        }
    
        // 返回新的版本号
        return major + '.' + minor + '.' + patch;
    }


    /**
     * 获取创建应用详情
     */
    @observable data: PluginCodeInfo;
    @action setData = (info) => {
        this.data = {
            ...info,
            modules: info.modules.map((o) => ({ ...o, content: JSON.parse(o.content) })),
            pages: info.pages.map((o) => ({ ...o, content: JSON.parse(o.content) })),
        };
    }


    /**
     * 创建build构建文件
     */
    createBuildFile = async () => {
        const { plugin, menus, pages, modules, languages } = this.data;
        
        for (const element of modules) {
            element.key = element.moduleId;
            element.source = 'custom';
            moduleStore.addElement(element as any);   
        }
        const modulesList = await Promise.all(modules.map((o) => {
            return (async () => {
                const { content, ...item } = o;
                const moduleStore = new CustomPageStore({ isComponent: true })
                await moduleStore.setData(content)
                return {
                    ...item,
                    jsxRender: await moduleStore.getRenderText(),
                }
            })()
        }))

        const pagesList = await Promise.all(pages.map((o) => {
            return (async () => {
                const { content, ...item } = o;
                const moduleStore = new CustomPageStore({ })
                await moduleStore.setData(content)
                return {
                    ...item,
                    jsxRender: await moduleStore.getRenderText(),
                }
            })()
        }))

        return `export default ${JSON.stringify({
            plugin,
            menus,
            languages,
            pages: pagesList,
            modules: modulesList,
        })}`
    }

    /**
     * 版本创建
     */
    createVersion = async (res: any) => {
        const { versionNumber } = res;
        const pluginId = plugin.info.id;
        const data = await ajax.post('/plugin/pluginInformation-code', { pluginId });
        this.setData(data);

        // 上传文件( build 版本包 )
        await uploadOSSFile(
            await this.createBuildFile(),
            dir.plugin.getBuildPath(pluginId, versionNumber),
        )
        
        // 上传文件( code 版本 )
        await uploadOSSFile(
            `export default ${JSON.stringify(toJS(this.data))}`,
            dir.plugin.getPath(pluginId, versionNumber),
        )

        
        // 创建版本
        return ajax.post('/plugin/versionCreate', {
            pluginId,
            ...res
        }).then((res) => {
            Message.success("版本创建成功")
            this.setVisible(false);
            this.init();
        })
    }

}


export default Store;